<?php
namespace Modules\Ran\Reports;
class ProductionReport extends AbstractRanReport{public function title():string{return 'Production Orders';}public function headings():array{return ['Order No','Date','Due Date','Status','Artisan','Estimated Cost','Actual Cost'];}public function rows(array $f):array{$q=\DB::table('ran_production_orders as p')->leftJoin('ran_artisans as a','a.id','=','p.artisan_id')->whereNull('p.deleted_at');$this->filter($q,$f,'p.order_date','p');return $q->orderByDesc('p.order_date')->get(['p.order_no','p.order_date','p.due_date','p.status','a.name as artisan','p.estimated_cost','p.actual_cost'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Estimated Cost'=>array_sum(array_column($rows,'estimated_cost')),'Actual Cost'=>array_sum(array_column($rows,'actual_cost'))];}}
